const express = require('express');
const { NotificationServiceClient } = require('@acme/notification-client');
const { requireAuth } = require('../auth');
const { Template } = require('../models/Template');

const app = express();
app.use(express.json());

const notificationClient = new NotificationServiceClient({
  internalHost: 'http://notifications.svc.cluster.local:4000',
  serviceSecret: process.env.ACME_INTERNAL_SECRET
});

app.post('/api/campaigns/send-test', requireAuth, async (req, res) => {
  const { templateId, recipientPhone, samplePayload } = req.body;

  // Confirm that the template belongs to the authenticated user's organization
  const template = await Template.findOne({
    where: {
      id: templateId,
      organizationId: req.user.organizationId
    }
  });

  if (!template) {
    return res.status(404).json({ error: 'SMS template not found in your organization' });
  }

  try {
    const dispatchResult = await notificationClient.dispatchSmsTemplate({
      templateId: template.id,
      organizationId: req.user.organizationId,
      to: recipientPhone,
      variables: samplePayload
    });

    res.json({ status: 'dispatched', messageId: dispatchResult.id });
  } catch (err) {
    res.status(500).json({ error: 'Notification service failure' });
  }
});

app.listen(8083);
